#!/usr/bin/env python3
import json
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote_to_bytes

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"


def open_db():
    conn = sqlite3.connect(DB_PATH, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=30000")
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=FULL")
    return conn


class QueueHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def _send(self, status, body=b"", content_type=None):
        self.send_response(status)
        if content_type is not None:
            self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _job_id(self):
        path = self.path.split("?", 1)[0]
        parts = path.split("/")
        if len(parts) != 3 or parts[1] != "jobs" or not parts[2]:
            return None
        try:
            return unquote_to_bytes(parts[2]).decode("utf-8")
        except UnicodeDecodeError:
            return None

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self._send(200, b"ready")
            return

        job_id = self._job_id()
        if job_id is None:
            self._send(404)
            return

        conn = open_db()
        try:
            row = conn.execute(
                "SELECT id, payload, status, result, attempts FROM jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                self._send(404)
                return
            body = json.dumps(
                {
                    "id": row["id"],
                    "payload": row["payload"],
                    "status": row["status"],
                    "result": row["result"],
                    "attempts": int(row["attempts"]),
                },
                ensure_ascii=False,
                separators=(",", ":"),
            ).encode("utf-8")
            self._send(200, body, "application/json; charset=utf-8")
        finally:
            conn.close()

    def do_POST(self):
        job_id = self._job_id()
        if job_id is None:
            self._send(404)
            return

        length_header = self.headers.get("Content-Length")
        try:
            length = 0 if length_header is None else int(length_header)
            if length < 0:
                raise ValueError
        except ValueError:
            self._send(400)
            return

        try:
            payload = self.rfile.read(length).decode("utf-8")
        except UnicodeDecodeError:
            self._send(400)
            return

        conn = open_db()
        try:
            with conn:
                conn.execute(
                    "INSERT OR IGNORE INTO jobs (id, payload, status, result, attempts) "
                    "VALUES (?, ?, 'queued', NULL, 0)",
                    (job_id, payload),
                )
            self._send(202)
        except sqlite3.Error:
            self._send(500)
        finally:
            conn.close()

    def log_message(self, format, *args):
        return


if __name__ == "__main__":
    server = ThreadingHTTPServer(("0.0.0.0", 8080), QueueHandler)
    server.serve_forever()

#!/usr/bin/env python3
import signal
import sqlite3
import time

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"
POLL_INTERVAL = 0.1


def open_db():
    conn = sqlite3.connect(DB_PATH, timeout=30)
    conn.execute("PRAGMA busy_timeout=30000")
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=FULL")
    return conn


def process_one(conn):
    conn.execute("BEGIN IMMEDIATE")
    row = conn.execute(
        "SELECT id, payload FROM jobs "
        "WHERE status = 'queued' AND attempts = 0 "
        "ORDER BY rowid LIMIT 1"
    ).fetchone()
    if row is None:
        conn.rollback()
        return False

    conn.execute(
        "UPDATE jobs SET status = 'completed', result = ?, attempts = 1 "
        "WHERE id = ? AND status = 'queued' AND attempts = 0",
        ("processed:" + row[1], row[0]),
    )
    conn.commit()
    return True


def run():
    conn = open_db()
    try:
        while True:
            try:
                if not process_one(conn):
                    time.sleep(POLL_INTERVAL)
            except sqlite3.Error:
                conn.rollback()
                time.sleep(POLL_INTERVAL)
    finally:
        conn.close()


if __name__ == "__main__":
    run()

